insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('omlet-s-ovoschami-i-syrom', 'breakfast', true, null, 15, 240, 2, 'easy',
   '{"ru":"Омлет с овощами и сыром","en":"Veggie and cheese omelette","ua":"Омлет з овочами та сиром"}'::jsonb,
   '{"ru":"Пышный омлет с сочными помидорами, перцем и тянущимся сыром. Белковый завтрак, который заряжает энергией и готовится быстрее, чем варится кофе.","en":"A fluffy omelette with juicy tomatoes, pepper and melty cheese. A protein breakfast that fuels the morning and cooks faster than your coffee brews.","ua":"Пишний омлет із соковитими помідорами, перцем і тягучим сиром. Білковий сніданок, що заряджає енергією й готується швидше, ніж вариться кава."}'::jsonb,
   '{"ru":["Яйца — 4 шт.","Молоко — 60 мл","Помидор — 1 шт.","Болгарский перец — половина","Твёрдый сыр — 50 г","Зелень — по вкусу","Сливочное масло — 10 г","Соль и перец — по вкусу"],"en":["Eggs — 4","Milk — 60 ml","Tomato — 1","Bell pepper — half","Hard cheese — 50 g","Herbs — to taste","Butter — 10 g","Salt and pepper — to taste"],"ua":["Яйця — 4 шт.","Молоко — 60 мл","Помідор — 1 шт.","Болгарський перець — половина","Твердий сир — 50 г","Зелень — до смаку","Вершкове масло — 10 г","Сіль і перець — до смаку"]}'::jsonb,
   '{"ru":["Взбейте яйца с молоком, солью и перцем.","Обжарьте нарезанные овощи на масле 2–3 минуты.","Влейте яичную смесь и готовьте на слабом огне под крышкой.","Посыпьте тёртым сыром и зеленью, дайте сыру расплавиться.","Сложите омлет пополам и подавайте сразу."],"en":["Whisk the eggs with milk, salt and pepper.","Fry the chopped vegetables in butter for 2–3 minutes.","Pour in the egg mix and cook over low heat, covered.","Scatter with grated cheese and herbs, let the cheese melt.","Fold the omelette in half and serve at once."],"ua":["Збийте яйця з молоком, сіллю та перцем.","Обсмажте нарізані овочі на маслі 2–3 хвилини.","Влийте яєчну суміш і готуйте на слабкому вогні під кришкою.","Посипте тертим сиром і зеленню, дайте сиру розплавитися.","Складіть омлет навпіл і подавайте одразу."]}'::jsonb,
   '{"ru":["ПП","завтрак","яйца","быстро"],"en":["healthy","breakfast","eggs","quick"],"ua":["ПХ","сніданок","яйця","швидко"]}'::jsonb)
