  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('shakshuka', 'breakfast', false, null, 25, 260, 2, 'easy',
   '{"ru":"Шакшука — яйца в томатном соусе","en":"Shakshuka — eggs in tomato sauce","ua":"Шакшука — яйця в томатному соусі"}'::jsonb,
   '{"ru":"Яйца, запечённые в пряном томатном соусе с перцем и специями. Средиземноморский завтрак прямо на сковороде — сытно, ярко и с ароматным хлебом для макания.","en":"Eggs poached in a spiced tomato sauce with peppers and warm spices. A Mediterranean breakfast straight from the pan — hearty, vivid and made for dunking bread.","ua":"Яйця, запечені в пряному томатному соусі з перцем і спеціями. Середземноморський сніданок просто на сковороді — ситно, яскраво й з ароматним хлібом для вмочання."}'::jsonb,
   '{"ru":["Яйца — 4 шт.","Помидоры — 400 г","Болгарский перец — 1 шт.","Лук — 1 шт.","Чеснок — 2 зубчика","Паприка — 1 ч. л.","Зира — 0,5 ч. л.","Оливковое масло — 2 ст. л.","Соль и перец — по вкусу"],"en":["Eggs — 4","Tomatoes — 400 g","Bell pepper — 1","Onion — 1","Garlic — 2 cloves","Paprika — 1 tsp","Cumin — 0.5 tsp","Olive oil — 2 tbsp","Salt and pepper — to taste"],"ua":["Яйця — 4 шт.","Помідори — 400 г","Болгарський перець — 1 шт.","Цибуля — 1 шт.","Часник — 2 зубчики","Паприка — 1 ч. л.","Кмин — 0,5 ч. л.","Оливкова олія — 2 ст. л.","Сіль і перець — до смаку"]}'::jsonb,
   '{"ru":["Обжарьте лук и перец на оливковом масле до мягкости.","Добавьте чеснок и специи, прогрейте до аромата.","Влейте измельчённые помидоры и тушите 8–10 минут до густоты.","Сделайте углубления и вбейте яйца, накройте крышкой.","Готовьте, пока белок схватится, а желток останется жидким. Подавайте с хлебом."],"en":["Fry the onion and pepper in olive oil until soft.","Add the garlic and spices, warm until fragrant.","Pour in the chopped tomatoes and simmer 8–10 minutes until thick.","Make wells and crack in the eggs, then cover.","Cook until the whites set but the yolks stay runny. Serve with bread."],"ua":["Обсмажте цибулю й перець на оливковій олії до м''якості.","Додайте часник і спеції, прогрійте до аромату.","Влийте подрібнені помідори й тушкуйте 8–10 хвилин до густоти.","Зробіть заглиблення й вбийте яйця, накрийте кришкою.","Готуйте, поки білок схопиться, а жовток лишиться рідким. Подавайте з хлібом."]}'::jsonb,
   '{"ru":["завтрак","яйца","томаты"],"en":["breakfast","eggs","tomato"],"ua":["сніданок","яйця","томати"]}'::jsonb)
on conflict (slug) do update set
