  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('lenivaya-ovsyanka-v-banke', 'breakfast', true, null, 10, 280, 1, 'easy',
   '{"ru":"Ленивая овсянка в банке","en":"Overnight oats in a jar","ua":"Лінива вівсянка в банці"}'::jsonb,
   '{"ru":"Овсянку не нужно варить: с вечера залил йогуртом и молоком, а утром достал готовый завтрак с ягодами и мёдом. Идеально, когда нет времени на готовку.","en":"No cooking needed: mix with yoghurt and milk the night before, and in the morning you have a ready breakfast with berries and honey. Perfect when there''s no time to cook.","ua":"Вівсянку не треба варити: з вечора залив йогуртом і молоком, а вранці дістав готовий сніданок із ягодами й медом. Ідеально, коли немає часу на готування."}'::jsonb,
   '{"ru":["Овсяные хлопья — 50 г","Йогурт — 100 г","Молоко — 100 мл","Мёд — 1 ч. л.","Ягоды — 60 г","Семена чиа — 1 ч. л."],"en":["Rolled oats — 50 g","Yoghurt — 100 g","Milk — 100 ml","Honey — 1 tsp","Berries — 60 g","Chia seeds — 1 tsp"],"ua":["Вівсяні пластівці — 50 г","Йогурт — 100 г","Молоко — 100 мл","Мед — 1 ч. л.","Ягоди — 60 г","Насіння чіа — 1 ч. л."]}'::jsonb,
   '{"ru":["В банку всыпьте хлопья и семена чиа.","Влейте молоко и йогурт, добавьте мёд, перемешайте.","Закройте крышкой и уберите в холодильник на ночь.","Утром добавьте ягоды и при желании орехи.","Совет: регулируйте густоту молоком — за ночь овсянка загустеет."],"en":["Put the oats and chia seeds into a jar.","Pour in the milk and yoghurt, add honey and stir.","Close the lid and refrigerate overnight.","In the morning top with berries and nuts if you like.","Tip: adjust the thickness with milk — the oats thicken overnight."],"ua":["У банку всипте пластівці й насіння чіа.","Влийте молоко та йогурт, додайте мед, перемішайте.","Закрийте кришкою й приберіть у холодильник на ніч.","Вранці додайте ягоди й за бажанням горіхи.","Порада: регулюйте густоту молоком — за ніч вівсянка загусне."]}'::jsonb,
   '{"ru":["ПП","завтрак","овсянка","без готовки"],"en":["healthy","breakfast","oats","no-cook"],"ua":["ПХ","сніданок","вівсянка","без готування"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
  calories = excluded.calories,
  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('domashnyaya-granola', 'breakfast', true, null, 35, 300, 6, 'easy',
   '{"ru":"Домашняя гранола","en":"Homemade granola","ua":"Домашня гранола"}'::jsonb,
   '{"ru":"Хрустящая гранола из овсянки, орехов и мёда, запечённая до золотистых кластеров. Полезнее магазинной, без лишнего сахара — с молоком, йогуртом или просто горстью.","en":"Crunchy granola of oats, nuts and honey, baked into golden clusters. Healthier than shop-bought and lower in sugar — with milk, yoghurt or just a handful.","ua":"Хрустка гранола з вівсянки, горіхів і меду, запечена до золотистих кластерів. Корисніша за магазинну, без зайвого цукру — з молоком, йогуртом чи просто жменею."}'::jsonb,
   '{"ru":["Овсяные хлопья — 250 г","Орехи микс — 100 г","Мёд — 3 ст. л.","Растительное масло — 2 ст. л.","Семечки — 40 г","Сухофрукты — 80 г","Корица — 0,5 ч. л."],"en":["Rolled oats — 250 g","Mixed nuts — 100 g","Honey — 3 tbsp","Vegetable oil — 2 tbsp","Seeds — 40 g","Dried fruit — 80 g","Cinnamon — 0.5 tsp"],"ua":["Вівсяні пластівці — 250 г","Горіхи мікс — 100 г","Мед — 3 ст. л.","Олія — 2 ст. л.","Насіння — 40 г","Сухофрукти — 80 г","Кориця — 0,5 ч. л."]}'::jsonb,
   '{"ru":["Смешайте хлопья, орехи, семечки и корицу.","Добавьте мёд и масло, тщательно перемешайте.","Выложите ровным слоем на противень с пергаментом.","Запекайте при 160 °C 25–30 минут, помешивая каждые 10 минут.","Остудите полностью, затем вмешайте сухофрукты — так гранола станет хрустящей."],"en":["Mix the oats, nuts, seeds and cinnamon.","Add the honey and oil and toss thoroughly.","Spread in an even layer on a lined baking sheet.","Bake at 160 °C for 25–30 minutes, stirring every 10 minutes.","Cool completely, then stir in the dried fruit — that''s what makes it crunchy."],"ua":["Змішайте пластівці, горіхи, насіння й корицю.","Додайте мед і олію, ретельно перемішайте.","Викладіть рівним шаром на деко з пергаментом.","Запікайте за 160 °C 25–30 хвилин, помішуючи кожні 10 хвилин.","Остудіть повністю, потім вмішайте сухофрукти — так гранола стане хрусткою."]}'::jsonb,
   '{"ru":["ПП","завтрак","гранола","овсянка"],"en":["healthy","breakfast","granola","oats"],"ua":["ПХ","сніданок","гранола","вівсянка"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
  calories = excluded.calories,
  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
