  ('frantsuzskie-grenki', 'breakfast', false, null, 15, 320, 2, 'easy',
   '{"ru":"Французские гренки (френч-тост)","en":"French toast","ua":"Французькі грінки (френч-тост)"}'::jsonb,
   '{"ru":"Ломтики хлеба в сладком яично-молочном кляре, обжаренные до золотистой карамельной корочки. Подавайте с мёдом, ягодами или сгущёнкой — уютный завтрак выходного дня.","en":"Slices of bread in a sweet egg-and-milk custard, fried to a golden caramel crust. Serve with honey, berries or condensed milk — a cosy weekend breakfast.","ua":"Скибочки хліба в солодкому яєчно-молочному клярі, обсмажені до золотистої карамельної скоринки. Подавайте з медом, ягодами чи згущівкою — затишний сніданок вихідного дня."}'::jsonb,
   '{"ru":["Хлеб (батон) — 6 ломтиков","Яйца — 2 шт.","Молоко — 100 мл","Сахар — 1 ст. л.","Ванильный сахар — 1 ч. л.","Сливочное масло — для жарки"],"en":["Bread (loaf) — 6 slices","Eggs — 2","Milk — 100 ml","Sugar — 1 tbsp","Vanilla sugar — 1 tsp","Butter — for frying"],"ua":["Хліб (батон) — 6 скибочок","Яйця — 2 шт.","Молоко — 100 мл","Цукор — 1 ст. л.","Ванільний цукор — 1 ч. л.","Вершкове масло — для смаження"]}'::jsonb,
   '{"ru":["Взбейте яйца с молоком, сахаром и ванилью.","Обмакивайте ломтики хлеба в смесь с двух сторон.","Обжаривайте на сливочном масле до золотистой корочки.","Переверните и подрумяньте вторую сторону.","Подавайте тёплыми с мёдом, ягодами или сиропом."],"en":["Whisk the eggs with milk, sugar and vanilla.","Dip the bread slices in the mix on both sides.","Fry in butter until golden.","Flip and brown the other side.","Serve warm with honey, berries or syrup."],"ua":["Збийте яйця з молоком, цукром і ваніллю.","Вмочайте скибочки хліба в суміш із двох боків.","Обсмажуйте на вершковому маслі до золотистої скоринки.","Переверніть і підрум''яньте другий бік.","Подавайте теплими з медом, ягодами чи сиропом."]}'::jsonb,
   '{"ru":["завтрак","хлеб","яйца","сладкое"],"en":["breakfast","bread","eggs","sweet"],"ua":["сніданок","хліб","яйця","солодке"]}'::jsonb)
