values
  ('amerikanskie-pankeyki', 'breakfast', false, null, 25, 300, 3, 'easy',
   '{"ru":"Американские панкейки","en":"American pancakes","ua":"Американські панкейки"}'::jsonb,
   '{"ru":"Толстенькие пышные панкейки, как из американских фильмов — стопкой, с маслом и кленовым сиропом. Секрет пышности — кефир и не перемешивать тесто слишком долго.","en":"Thick, fluffy pancakes like in the movies — stacked with butter and maple syrup. The secret to the rise is buttermilk and not overmixing the batter.","ua":"Товстенькі пишні панкейки, як з американських фільмів — стосом, з маслом і кленовим сиропом. Секрет пишності — кефір і не перемішувати тісто надто довго."}'::jsonb,
   '{"ru":["Мука — 200 г","Кефир — 250 мл","Яйцо — 1 шт.","Сахар — 2 ст. л.","Разрыхлитель — 1 ч. л.","Сода — 0,5 ч. л.","Сливочное масло — 30 г","Щепотка соли"],"en":["Flour — 200 g","Buttermilk — 250 ml","Egg — 1","Sugar — 2 tbsp","Baking powder — 1 tsp","Baking soda — 0.5 tsp","Butter — 30 g","A pinch of salt"],"ua":["Борошно — 200 г","Кефір — 250 мл","Яйце — 1 шт.","Цукор — 2 ст. л.","Розпушувач — 1 ч. л.","Сода — 0,5 ч. л.","Вершкове масло — 30 г","Дрібка солі"]}'::jsonb,
   '{"ru":["Смешайте сухие ингредиенты в одной миске.","В другой соедините кефир, яйцо и растопленное масло.","Быстро соедините смеси — комочки допустимы, не перемешивайте долго.","Выпекайте на сухой сковороде до пузырьков, затем переверните.","Складывайте стопкой и подавайте с сиропом или ягодами."],"en":["Mix the dry ingredients in one bowl.","In another, combine buttermilk, egg and melted butter.","Quickly fold together — lumps are fine, don''t overmix.","Cook on a dry pan until bubbles form, then flip.","Stack them up and serve with syrup or berries."],"ua":["Змішайте сухі інгредієнти в одній мисці.","В іншій поєднайте кефір, яйце й розтоплене масло.","Швидко поєднайте суміші — грудочки припустимі, не перемішуйте довго.","Випікайте на сухій сковороді до бульбашок, потім переверніть.","Складайте стосом і подавайте із сиропом чи ягодами."]}'::jsonb,
   '{"ru":["завтрак","панкейки","сладкое"],"en":["breakfast","pancakes","sweet"],"ua":["сніданок","панкейки","солодке"]}'::jsonb)
