insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('risovaya-kasha-na-moloke', 'breakfast', false, null, 30, 220, 3, 'easy',
   '{"ru":"Рисовая каша на молоке","en":"Creamy milk rice porridge","ua":"Рисова каша на молоці"}'::jsonb,
   '{"ru":"Нежная молочная рисовая каша — тёплый уютный завтрак родом из детства. Кремовая текстура достигается на медленном огне, а сверху — кусочек масла.","en":"A tender milk rice porridge — a warm, comforting breakfast straight from childhood. The creamy texture comes from slow cooking, finished with a knob of butter.","ua":"Ніжна молочна рисова каша — теплий затишний сніданок родом із дитинства. Кремова текстура досягається на повільному вогні, а зверху — шматочок масла."}'::jsonb,
   '{"ru":["Рис круглозёрный — 120 г","Молоко — 600 мл","Вода — 200 мл","Сахар — 2 ст. л.","Сливочное масло — 20 г","Щепотка соли"],"en":["Round rice — 120 g","Milk — 600 ml","Water — 200 ml","Sugar — 2 tbsp","Butter — 20 g","A pinch of salt"],"ua":["Рис круглозернистий — 120 г","Молоко — 600 мл","Вода — 200 мл","Цукор — 2 ст. л.","Вершкове масло — 20 г","Дрібка солі"]}'::jsonb,
   '{"ru":["Промойте рис и залейте водой, варите 5 минут до впитывания.","Влейте молоко и доведите до лёгкого кипения.","Варите на медленном огне 20 минут, помешивая, чтобы не пригорело.","Добавьте сахар и соль, прогрейте пару минут.","Снимите с огня, положите масло и дайте настояться под крышкой."],"en":["Rinse the rice, add water and cook 5 minutes until absorbed.","Pour in the milk and bring to a gentle simmer.","Cook on low for 20 minutes, stirring so it doesn''t catch.","Add sugar and salt and warm a couple of minutes.","Off the heat, add butter and let it rest, covered."],"ua":["Промийте рис і залийте водою, варіть 5 хвилин до вбирання.","Влийте молоко й доведіть до легкого кипіння.","Варіть на повільному вогні 20 хвилин, помішуючи, щоб не пригоріло.","Додайте цукор і сіль, прогрійте пару хвилин.","Зніміть з вогню, покладіть масло й дайте настоятися під кришкою."]}'::jsonb,
   '{"ru":["завтрак","каша","рис","молоко"],"en":["breakfast","porridge","rice","milk"],"ua":["сніданок","каша","рис","молоко"]}'::jsonb)
